@extends('layouts.app') @section('title',($record->exists?'Edit ':'Create ').Str::singular($title)) @section('content')<div class="page-head"><div><a class="link" href="/manage/{{ $resource }}">← {{ $title }}</a><h1 style="margin-top:12px">{{ $record->exists?'Edit':'Create' }} {{ Str::singular($title) }}</h1></div></div><form class="card pad" method="POST" enctype="multipart/form-data" action="/manage/{{ $resource }}{{ $record->exists?'/'.$record->id:'' }}">@csrf @if($record->exists)@method('PUT')@endif<div class="form-grid">@foreach($fields as $field=>$type)@php($value=old($field,$record->$field))@php($value=is_bool($value)?(int)$value:$value)@php($label=ucfirst(str_replace(['_id','_'],['',' '],$field)))<div class="field {{ $type==='textarea'?'wide':'' }}"><label for="{{ $field }}">{{ $label }}</label>@if(is_array($type)||isset($options[$type]))<select id="{{ $field }}" name="{{ $field }}">@if(!is_array($type))<option value="">Select {{ strtolower($label) }}</option>@endif @foreach(is_array($type)?$type:$options[$type] as $key=>$text)<option value="{{ $key }}" @selected((string)$value===(string)$key)>{{ $text }}</option>@endforeach</select>@elseif($type==='textarea')<textarea name="{{ $field }}" id="{{ $field }}" rows="5">{{ is_array($value)?implode("\n",$value):$value }}</textarea>@elseif(in_array($type,['image','file']))<input id="{{ $field }}" name="{{ $field }}" type="file" @if($type==='image') accept="image/png,image/jpeg,image/webp" @endif>@if($value)<small>A file is attached. Upload a file to replace it.</small>@endif @else<input id="{{ $field }}" name="{{ $field }}" type="{{ $type }}" value="{{ $type==='password'?'':($value instanceof \Carbon\Carbon ? $value->format('Y-m-d\TH:i') : $value) }}" @if($type==='number') min="0" @endif @if($type==='password') autocomplete="new-password" @endif>@endif @if($field==='options')<small>One option per line. True/false questions use “True” and “False”.</small>@elseif($field==='answer')<small>Match an option exactly. Shor